package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class JsonWriter_nullValue_TriageGen0Test {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @After
    public void tearDown() throws IOException {
        jsonWriter.close();
    }

    @Test
    public void testNullValueWithSerializeNullsTrueAndDeferredNameNotNull() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.name("testName");
        jsonWriter.nullValue();
        assertEquals("{\"testName\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndDeferredNameNotNull() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.name("testName");
        jsonWriter.nullValue();
        assertEquals("{\"testName\":", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsTrueAndDeferredNameNull() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.nullValue();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndDeferredNameNull() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.nullValue();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsTrueAndNoDeferredName() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.beginObject();
        jsonWriter.nullValue();
        jsonWriter.endObject();
        assertEquals("{}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndNoDeferredName() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject();
        jsonWriter.nullValue();
        jsonWriter.endObject();
        assertEquals("{}", stringWriter.toString());
    }
}
